      if(G._bossLoadFade>=1){G._bossLoadPhase=2;G._bossLoadT=0;_enterBossArena()}
    }else if(G._bossLoadPhase===2){// 보스 네임카드
      G._bossLoadFade=1;
      if(G._bossLoadT>=130){G._bossLoadPhase=3;G._bossLoadT=0}
    }else if(G._bossLoadPhase===3){// 페이드 인
      G._bossLoadFade=Math.max(0,1-G._bossLoadT/50);
      if(G._bossLoadFade<=0){G._bossLoadPhase=4;G._bossLoadT=0;G._bossLoadFade=0}
    }else if(G._bossLoadPhase===4){// 보스 입장 연출 (100f)
      if(G._bossLoadT<2){
        const _bE=findBoss();
        if(_bE){
          _bE.stunned=90;_bE.reviveIframes=110; // 1.5초 무적+경직
          shake(28);G._flashT=10;G._flashCol='#ff4400';G._chromaT=12;G.slowMo=Math.max(G.slowMo,60);
          // 입장 파티클 링
          for(let _bi=0;_bi<32;_bi++){const _ba=Math.PI*2*_bi/32,_br=_bE.r*2.5;
    for(let _ri=0;!_blocked&&_ri<8;_ri++){
      const _a=Math.PI*2*_ri/8;
      _blocked=wallFn(_x+Math.cos(_a)*_r,_y+Math.sin(_a)*_r);
    }
    if(_blocked)return{x:_lastX,y:_lastY};
    _lastX=_x;_lastY=_y;
  }
