function salvageVal(it){
  const e=it.enh||0;
  // 강화분 환수는 레거시 단위누적식의 50%이며 현행 enhCostRaw 지출의 50%가 아님.
  // 레거시 누적항: ceil(max(1,ceil((1+i*0.15)*1.5))*등급배율). PM-013-D 설계 대기.
  let enhRefund=0;
  if(e>0){
    const rMul=[0.5,0.7,1.0,1.3,1.8][_itemEconomyRarity(it.rarity)];
    let totalCost=0;
    for(let i=0;i<e;i++) totalCost+=Math.ceil(Math.max(1,Math.ceil((1+i*0.15)*1.5))*rMul);
    enhRefund=Math.floor(totalCost*0.5);
  }
  // 강화 이전된 구 장비: 이전 시 기록된 투자분 환불
  if(it._enhRefund>0)enhRefund=Math.max(enhRefund,it._enhRefund);
  return[1000,2000,10000,20000,50000][_itemEconomyRarity(it.rarity)]+enhRefund+(it.tier||0)*2;
}
